from math import gcd, isqrt
from typing import List

def is_prime(p: int) -> bool:
    if p < 2: return False
    if p % 2 == 0: return p == 2
    for d in range(3, isqrt(p) + 1, 2):
        if p % d == 0: return False
    return True

def primes_up_to(limit: int) -> List[int]:
    return [p for p in range(2, limit + 1) if is_prime(p)]

def sol_set(p: int) -> List[int]:
    """Roots of x^2 + 1 == 0 (mod p) in {0,...,p-1}; mirrors Lean `solSet`."""
    return [x for x in range(p) if (x * x + 1) % p == 0]

def verify_solvability_and_counts(limit: int = 200) -> None:
    """Check solvable_iff, card_solSet_of_ne, card_solSet_of_three exhaustively."""
    for p in primes_up_to(limit):
        roots = sol_set(p)
        if p == 2:
            expected = 1
        elif p % 4 == 3:
            expected = 0          # card_solSet_of_three
        else:
            expected = 2          # card_solSet_of_ne
        solvable = len(roots) > 0
        assert solvable == (p % 4 != 3), p          # solvable_iff
        assert len(roots) == expected, (p, roots)
        print(f"p={p:>4}  p%4={p%4}  #roots={len(roots)}  roots={roots}")
    print("solvable_iff and exact-count theorems verified for all primes up to", limit)

if __name__ == "__main__":
    verify_solvability_and_counts()

from math import gcd, isqrt
from typing import List

def is_prime(p: int) -> bool:
    if p < 2: return False
    if p % 2 == 0: return p == 2
    for d in range(3, isqrt(p) + 1, 2):
        if p % d == 0: return False
    return True

def sol_set(p: int) -> List[int]:
    return [x for x in range(p) if (x * x + 1) % p == 0]

def nu(p: int, n: int) -> int:
    """Local density factor nu_p(n): roots of x^2+1=0 (mod p) coprime to n."""
    return sum(1 for x in sol_set(p) if gcd(x, n) == 1)

def verify_nu(limit: int = 100, test_ns=(1, 6, 30, 210)) -> None:
    """Exercise nu_le_two and nu_eq_zero_of_three across odd primes."""
    for p in range(3, limit + 1):
        if not is_prime(p):
            continue
        for n in test_ns:
            v = nu(p, n)
            assert v <= 2, (p, n, v)              # nu_le_two
            if p % 4 == 3:
                assert v == 0, (p, n, v)          # nu_eq_zero_of_three
        print(f"p={p:>4} p%4={p%4} " +
              " ".join(f"nu(.,{n})={nu(p,n)}" for n in test_ns))
    print("nu_le_two and nu_eq_zero_of_three confirmed.")

if __name__ == "__main__":
    verify_nu()

