function MODULAR_ROOTS_SQ_PLUS_ONE(p):
    roots <- empty list
    for x from 0 to p-1:
        if (x*x + 1) mod p == 0:
            append x to roots
    return roots   # |roots| in {0,1,2}

function ADMISSIBLE_PRIME_FACTORS(N):
    P <- all primes up to N (sieve of Eratosthenes)
    return [ p in P : p == 2 OR p mod 4 == 1 ]

function LOCAL_DENSITY_FACTOR(p, n):
    roots <- MODULAR_ROOTS_SQ_PLUS_ONE(p)
    count <- 0
    for x in roots:
        if gcd(x, n) == 1:
            count <- count + 1
    return count   # in {0,1,2}
